const msg = $input.first().json;
const text = (msg.message?.text || '').trim();
const chatId = String(msg.message?.chat?.id || '');

let route = 'general';
let topic = text;

if (/^india\s*:/i.test(text)) {
  route = 'india';
  topic = text.replace(/^india\s*:\s*/i, '').trim();
}

// Stop silently if topic is empty (e.g. bot commands, empty messages)
if (!topic || topic.startsWith('/')) return [];

return [{ json: { route, topic, chatId } }];

const { topic, chatId } = $input.first().json;
const SERPAPI_KEY = 'YOUR_SERPAPI_KEY';
const BRAVE_KEY = 'YOUR_BRAVE_KEY';
const results = [];

// SerpAPI — Google web search
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://serpapi.com/search.json',
    qs: { engine: 'google', q: topic, num: 10, api_key: SERPAPI_KEY },
    timeout: 15000
  });
  for (const r of (res.organic_results || []).slice(0, 5)) {
    results.push({ title: r.title || '', url: r.link || '', snippet: r.snippet || '', source: 'Google' });
  }
} catch(e) {}

// Brave Search
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.search.brave.com/res/v1/web/search',
    headers: { 'X-Subscription-Token': BRAVE_KEY, 'Accept': 'application/json' },
    qs: { q: topic, count: 10 },
    timeout: 15000
  });
  for (const r of (res.web?.results || []).slice(0, 5)) {
    results.push({ title: r.title || '', url: r.url || '', snippet: r.description || '', source: 'Brave' });
  }
} catch(e) {}

return [{ json: { topic, results, chatId, route: 'general' } }];

const { topic, chatId } = $input.first().json;
const SERPAPI_KEY = 'YOUR_SERPAPI_KEY';
const NEWSDATA_KEY = 'YOUR_NEWSDATA_KEY';
const results = [];

// SerpAPI — Google News India
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://serpapi.com/search.json',
    qs: { engine: 'google_news', q: topic, gl: 'in', hl: 'en', api_key: SERPAPI_KEY },
    timeout: 15000
  });
  for (const r of (res.news_results || []).slice(0, 5)) {
    results.push({ title: r.title || '', url: r.link || '', snippet: r.snippet || '', source: r.source?.name || 'Google News' });
  }
} catch(e) {}

// NewsData.io — India (country=in)
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://newsdata.io/api/1/news',
    qs: { country: 'in', language: 'en', q: topic, apikey: NEWSDATA_KEY },
    timeout: 15000
  });
  for (const a of (res.results || []).slice(0, 5)) {
    results.push({ title: a.title || '', url: a.link || '', snippet: a.description || '', source: a.source_id || 'NewsData' });
  }
} catch(e) {}

return [{ json: { topic, results, chatId, route: 'india' } }];

const { topic, results, chatId, route } = $input.first().json;
const ANTHROPIC_KEY = 'YOUR_ANTHROPIC_KEY';
const BOT_TOKEN = 'YOUR_BOT_TOKEN';

const lines = results.map((r, i) =>
  (i + 1) + '. ' + r.title +
  '\n   Source: ' + r.source +
  '\n   ' + r.snippet +
  '\n   URL: ' + r.url
);
const context = results.length > 0 ? lines.join('\n\n') : 'No results found.';

const routeLabel = route === 'india' ? 'India news' : 'web research';
const prompt =
  'You are a research assistant. Summarize the following ' + routeLabel + ' search results for the topic: ' + topic +
  '\n\nWrite 3-5 concise bullet points covering the most important findings. Format your response using Telegram HTML: use <b>text</b> for bold headings and hyperlinks for sources. End with a Sources section listing up to 3 links.' +
  '\n\nSearch Results:\n' + context;

let replyText = '';
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': ANTHROPIC_KEY,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 1024,
      messages: [{ role: 'user', content: prompt }]
    }),
    timeout: 30000
  });
  replyText = res.content?.[0]?.text || 'No summary generated.';
} catch(e) {
  replyText = 'Error generating summary: ' + e.message;
}

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    chat_id: chatId,
    text: replyText,
    parse_mode: 'HTML',
    disable_web_page_preview: true
  }),
  timeout: 15000
});

return [{ json: { status: 'done', topic, route, resultsCount: results.length } }];
